export function normalizeCandidate(raw, { index = 0 } = {}) { const source = object(raw, 'candidate'); const kind = ALIASES[String(source.kind ?? '').trim().toLowerCase()] ?? String(source.kind ?? '').trim(); if (!CANDIDATE_KINDS.includes(kind)) throw new CandidateValidationError('kind is not supported: ' + kind); const operation = string(source.operation ?? source.action, 'operation'); if (!OPS[kind].includes(operation)) throw new CandidateValidationError('operation is not supported for ' + kind); const ev = evidence(source, index); const timelineContext = String(source.timelineContext ?? source.timeline_context ?? 'main').trim().toLowerCase(); if (!TIMELINE_CONTEXTS.includes(timelineContext)) throw new CandidateValidationError('timelineContext is not supported'); const value = valueFor(kind, source, ev.quote); const confidence = Number(source.confidence ?? 0); if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) throw new CandidateValidationError('confidence must be between 0 and 1'); return { schemaVersion: 1, kind, operation, subjectRef: subject(source, value), value, timelineContext, evidence: ev, confidence, modelUncertain: Boolean(source.modelUncertain ?? source.uncertain), modelProposalId: string(source.proposalId ?? source.id, 'proposalId', false) }; }
